mapper.select:
SELECT FROM performance_round_seat WHERE performance_round_seat_id IN
#{seatId}
ORDER BY performance_round_seat_id FOR UPDATE

mapper.insert:
INSERT INTO performance_round_seat (
    performance_round_id, seat_label, section_code,
    row_label, column_label, display_row, display_column,
    status_code, accessibility_code
) VALUES (
    #{performanceRoundId}, #{seatLabel}, #{sectionCode},
    #{rowLabel}, #{columnLabel}, #{displayRow}, #{displayColumn},
    #{status}, #{accessibilityCode}
)

mapper.update:
UPDATE performance_round_seat
SET status_code = #{status}
WHERE performance_round_seat_id = #{performanceRoundSeatId}

mapper.insert:
INSERT INTO reservation_seat (
    reservation_id, performance_round_seat_id,
    status_code, cancelled_dttm, cancel_reason,
    checked_in_dttm, checked_in_by_member_id
) VALUES (
    #{reservationId}, #{performanceRoundSeatId},
    #{status}, #{cancelledDttm}, #{cancelReason},
    #{checkedInDttm}, #{checkedInByMemberId}
)

INSERT INTO active_seat_occupancy (
    performance_round_seat_id, reservation_seat_id,
    occupied_dttm
) VALUES (
    #{performanceRoundSeatId}, #{reservationSeatId},
    #{occupiedDttm}
)

INSERT INTO reservation_status_history (
    reservation_id, previous_status_code,
    new_status_code, reason,
    changed_by_member_id, changed_dttm
) VALUES (
    #{reservationId}, #{previousStatus},
    #{newStatus}, #{reason},
    #{changedByMemberId}, #{changedDttm}
)

INSERT INTO seat_entry_history (
    reservation_seat_id, action_code,
    processed_by_member_id, processed_dttm, reason
) VALUES (
    #{reservationSeatId}, #{action},
    #{processedByMemberId}, #{processedDttm}, #{reason}
)
